package com.factoryflow.materials;

import jakarta.persistence.*;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/**
 * Entity mapping to the packaging_materials table.
 * Represents an individual packaging material (box, label, pouch, etc.)
 * used in the production / dispatch process.
 */
@Entity
@Table(name = "packaging_materials")
public class PackagingMaterial {

    /** Primary key – UUID generated by the application. */
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", updatable = false, nullable = false)
    private UUID id;

    /** Display name of the packaging material. */
    @Column(name = "name", nullable = false, length = 255)
    private String name;

    /** Short, unique code used for lookups and document references. */
    @Column(name = "code", nullable = false, unique = true, length = 50)
    private String code;

    /** Optional longer description or specification notes. */
    @Column(name = "description", nullable = true, columnDefinition = "TEXT")
    private String description;

    /** Unit of measure for this material (piece, roll, carton, etc.). */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "unit_id", nullable = true)
    private Unit unit;

    /**
     * Minimum stock level that triggers a reorder alert.
     * Stored as a decimal to support fractional units.
     */
    @Column(name = "reorder_level", nullable = true, precision = 15, scale = 4)
    private BigDecimal reorderLevel;

    /** Whether this material is currently in active use. Soft-delete flag. */
    @Column(name = "is_active", nullable = false)
    private boolean active = true;

    /** Audit timestamp set automatically on first insert. */
    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    /** Audit timestamp updated automatically on every save. */
    @UpdateTimestamp
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    public UUID getId() { return id; }
    public void setId(UUID id) { this.id = id; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getCode() { return code; }
    public void setCode(String code) { this.code = code; }
    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }
    public Unit getUnit() { return unit; }
    public void setUnit(Unit unit) { this.unit = unit; }
    public BigDecimal getReorderLevel() { return reorderLevel; }
    public void setReorderLevel(BigDecimal reorderLevel) { this.reorderLevel = reorderLevel; }
    public boolean isActive() { return active; }
    public void setActive(boolean active) { this.active = active; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public Instant getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(Instant updatedAt) { this.updatedAt = updatedAt; }
}
